function xDomain() {
  var lo = Infinity, hi = -Infinity;
  (data.series || []).forEach(function (s) {
    s.points.forEach(function (p) {
      var x = dayMs(p.date);
      if (x < lo) lo = x;
      if (x > hi) hi = x;
    });
  });
  return lo <= hi ? [lo, hi] : null;
}

// seriesFor turns the response into chart series: one per package per run, hue
// carrying the package and the dash pattern carrying the run. With one run
// selected the name is just the package, since the dash then says nothing.
function seriesFor(valueOf, subOf, only) {
  var runs = selectedMetrics();
  var solo = runs.length < 2;
  return (data.series || [])
    .filter(function (s) { return !only || s.metric === only; })
    .map(function (s) {
      return {
        name: solo || only ? s.package : s.package + ' · ' + shortLabelOf(s.metric),
        color: colorOf(s.package),
        dash: dashOf(s.metric),
        metric: s.metric,
        pkg: s.package,
        points: s.points.map(function (p) {
          return { x: dayMs(p.date), y: valueOf(p), sub: subOf ? subOf(p) : null, raw: p };
        })
      };
    });
}

// runLegend names the line styles once, under a chart whose colors are already
// named by the package chips. Two small legends beat one with a row per line.
function runLegend() {
  var runs = selectedMetrics();
  if (runs.length < 2) return '';
  return legend(runs.map(function (k) {
    return { color: 'var(--fg)', dash: dashOf(k), label: labelOf(k) };
  }));
}

function renderParity() {
  var host = document.getElementById('parity-body');
  var sub = document.getElementById('parity-sub');
  if (!state.selected.length) {
    sub.textContent = 'Percent of the reference surface matched, at the end of each day.';
    host.innerHTML = '<div class="empty">Pick a package above.</div>';
    return;
  }
  if (state.table) {
    sub.textContent = 'Percent of the reference surface matched, at the end of each day.';
    renderTable(host);
    return;
  }
  var s = seriesFor(function (p) { return p.percent; }, function (p) { return p.matched.toLocaleString() + ' / ' + p.total.toLocaleString() + ' · #' + p.pr; });
  if (!s.length) {
    sub.textContent = 'Percent of the reference surface matched, at the end of each day.';
    host.innerHTML = '<div class="empty">Pick a run above.</div>';
    return;
  }

  // Packages that have converged all sit in the last few points of the range,
  // where a 0–100 axis flattens every remaining move into one line. Zoom the
  // axis to the data when nothing is near the bottom — and say so in the
  // subhead, since a truncated axis exaggerates the wiggles it reveals. (A line
  // may leave the baseline; a bar never may.)
  var lo = 100;
  s.forEach(function (x) { x.points.forEach(function (p) { if (p.y < lo) lo = p.y; }); });
  var yMin = lo > 60 ? Math.max(0, Math.floor((lo - 2) / 5) * 5) : 0;
  sub.textContent = 'Percent of the reference surface matched, at the end of each day.' +
    (yMin > 0 ? ' Axis zoomed to ' + yMin + '–100%.' : '');

  // With several runs the per-line legend would be packages × runs entries, so
  // split it: colors are named once, line styles once.
  var pkgLegend = state.selected.length > 1
    ? legend(state.selected.map(function (p) { return { color: colorOf(p), label: p }; }))
    : '';
  host.innerHTML = '<div class="plot"></div>' + pkgLegend + runLegend();
  lineChart(host.querySelector('.plot'), s, {
    height: 320, yMin: yMin, yMax: 100, fmt: fmtPct,
    // End labels carry the series name, which is package · run here — past a
    // handful of lines they collide, so the legends do the naming instead.
    nameLabels: s.length <= 6, endLabels: s.length <= 6
  });
}

function renderCounts() {
  var host = document.getElementById('counts-body');
  if (!state.selected.length) { host.innerHTML = '<div class="empty">Pick a package above.</div>'; return; }
  // Small multiples: matched and total share a scale, so they share one axis —
  // one panel per package rather than one crowded chart.
  // One panel per package per run: the counts are on different scales run to
  // run (tests outnumber API methods), so they cannot share an axis.
  var rows = data.series || [];
  host.innerHTML = '<div class="smalls">' + rows.map(function () { return '<div class="plot"></div>'; }).join('') + '</div>' +
    legend([
      { color: 'var(--muted)', label: 'total (what parity is out of)', wash: true },
      { color: 'var(--muted)', label: 'matched' }
    ]);
  var plots = host.querySelectorAll('.plot');
  var domain = xDomain();
  var solo = selectedMetrics().length < 2;
  rows.forEach(function (s, i) {
    var c = colorOf(s.package);
    var totals = s.points.map(function (p) { return { x: dayMs(p.date), y: p.total }; });
    var matched = s.points.map(function (p) { return { x: dayMs(p.date), y: p.matched, sub: fmtPct(p.percent) }; });
    var max = Math.max.apply(null, totals.map(function (p) { return p.y; }).concat([1]));
    lineChart(plots[i], [
      { name: 'total', color: c, points: totals, area: true, dashed: true },
      { name: 'matched', color: c, points: matched }
    ], { height: 190, yMin: 0, yMax: max, fmt: fmtNum, endLabels: false,
         title: solo ? s.package : s.package + ' · ' + shortLabelOf(s.metric),
         padLeft: 52, xDomain: domain });
  });
}

// gapKeys is every gap the selected runs offer, as "<run>:<gap>" — a gap
// belongs to one run's table, so with several runs charted the picker has to
// say whose it is.
function gapKeys() {
  var byMetric = data.gaps_by_metric || {};
  var out = [];
  selectedMetrics().forEach(function (k) {
    (byMetric[k] || []).forEach(function (g) { out.push(k + ':' + g); });
  });
  return out;
}

function renderGaps() {
  var card = document.getElementById('gaps-card');
  var host = document.getElementById('gaps-body');
  var keys = gapKeys();
  card.style.display = keys.length ? '' : 'none';
  if (!keys.length) return;
  if (keys.indexOf(state.gap) < 0) state.gap = keys[0];

  var solo = selectedMetrics().length < 2;
  document.getElementById('gapSeg').innerHTML = keys.map(function (k) {
    var g = k.split(':')[1];
    return '<button class="' + (k === state.gap ? 'on' : '') + '" data-gap="' + esc(k) + '">' +
      esc(solo ? g : shortLabelOf(k.split(':')[0]) + ' · ' + g) + '</button>';
  }).join('');
  var run = state.gap.split(':')[0], gap = state.gap.split(':')[1];
  document.getElementById('gaps-sub').textContent = gapBlurb(gap);

  if (!state.selected.length) { host.innerHTML = '<div class="empty">Pick a package above.</div>'; return; }
  var s = seriesFor(function (p) { return (p.gaps || {})[gap] || 0; }, null, run);
  // All-zero is the good outcome, but as a chart it is a flat line on the
  // baseline that reads as "no data" — say which it is.
  var any = s.some(function (x) { return x.points.some(function (p) { return p.y > 0; }); });
  if (!any) {
    host.innerHTML = '<div class="empty">No ' + esc(gap) + ' recorded for ' +
      esc(state.selected.join(', ')) + ' in this range.</div>';
    return;
  }
  // The gap chart is one run's column, so every line here is solid and the
  // legend is back to one entry per package.
  s.forEach(function (x) { x.dash = ''; });
  host.innerHTML = '<div class="plot"></div>' +
    (s.length > 1 ? legend(s.map(function (x) { return { color: x.color, label: x.pkg }; })) : '');
  lineChart(host.querySelector('.plot'), s, { height: 240, yMin: 0, fmt: fmtNum, nameLabels: true });
}

function gapBlurb(gap) {
  if (gap === 'misplaced') return 'Methods (or tests) that exist but live on the wrong class or file — parity of content without parity of shape.';
  if (gap === 'missing') return 'Present in the reference surface, absent from the port.';
  if (gap === 'skipped') return 'Tests that exist but are skipped — counted as ported, not as passing.';
  if (gap === 'assertion_count_mismatch') return 'Mapped tests whose body makes a different NUMBER of assertions than the Ruby — ported in shape, not yet in substance. Advisory: it does not move the tests percent.';
  if (gap === 'assertion_kind_mismatch') return 'Mapped tests asserting different KINDS of things than the Ruby (an equality where Rails checks a raise, say). Advisory: it does not move the tests percent.';
  if (gap === 'mismatched') return 'Name-matched pairs where the ported body disagrees with the Ruby — a call Rails makes and the port omits, or a call site passing different arguments. Advisory: it does not move the parity percent.';
  return '';
}

function renderTable(host) {
  // Gap columns are per run, so the table shows the union and leaves a cell
  // blank where that run has no such column rather than printing a false zero.
  var byMetric = data.gaps_by_metric || {};
  var gaps = [];
  gapKeys().forEach(function (k) {
    var g = k.split(':')[1];
    if (gaps.indexOf(g) < 0) gaps.push(g);
  });
  var head = '<tr><th>Day</th><th>Run</th><th>Package</th><th class="num">Parity</th><th class="num">Matched</th><th class="num">Total</th>' +
    gaps.map(function (g) { return '<th class="num">' + esc(g) + '</th>'; }).join('') + '<th class="num">PR</th></tr>';
  var rows = [];
  (data.series || []).forEach(function (s) {
    s.points.forEach(function (p) {
      rows.push({ date: p.date, pkg: s.package, metric: s.metric, p: p });
    });
  });
  rows.sort(function (a, b) { return a.date < b.date ? 1 : a.date > b.date ? -1 : 0; });
  host.innerHTML = '<div class="tablewrap"><table><thead>' + head + '</thead><tbody>' +
    rows.map(function (r) {
      var has = byMetric[r.metric] || [];
      return '<tr><td>' + esc(fmtDay(r.date)) + '</td><td>' + esc(labelOf(r.metric)) + '</td><td>' + esc(r.pkg) + '</td>' +
        '<td class="num">' + fmtPct(r.p.percent) + '</td>' +
        '<td class="num">' + fmtNum(r.p.matched) + '</td>' +
        '<td class="num">' + fmtNum(r.p.total) + '</td>' +
        gaps.map(function (g) {
          return '<td class="num">' + (has.indexOf(g) < 0 ? '<span class="muted">—</span>' : fmtNum((r.p.gaps || {})[g] || 0)) + '</td>';
        }).join('') +
        '<td class="num"><a href="https://github.com/blazetrailsdev/trails/pull/' + r.p.pr + '" target="_blank">#' + r.p.pr + '</a></td></tr>';
    }).join('') + '</tbody></table></div>';
}

function renderControls() {
  document.getElementById('metricChips').innerHTML = metrics.map(function (m) {
    var on = state.metrics.indexOf(m.key) >= 0;
    // The chip's key shows the line style it draws with, so the picker and the
    // chart use one language.
    return '<button class="chip' + (on ? ' on' : '') + '" data-metric="' + esc(m.key) + '">' +
      '<svg class="key" width="14" height="4" viewBox="0 0 14 4" aria-hidden="true">' +
      '<line x1="0" y1="2" x2="14" y2="2" stroke="' + (on ? 'var(--fg)' : 'var(--border)') + '" stroke-width="2"' +
      (dashOf(m.key) ? ' stroke-dasharray="' + dashOf(m.key) + '"' : '') + '/></svg>' +
      esc(m.label) + '</button>';
  }).join('');
  document.getElementById('daysSeg').innerHTML = DAY_PRESETS.map(function (d) {
    return '<button class="' + (d[0] === state.days ? 'on' : '') + '" data-days="' + d[0] + '">' + d[1] + '</button>';
  }).join('');
  document.getElementById('chips').innerHTML = packages.map(function (pkg) {
    var on = state.selected.indexOf(pkg) >= 0;
    return '<button class="chip' + (on ? ' on' : '') + '" data-pkg="' + esc(pkg) + '">' +
      '<span class="key" style="background:' + (on ? colorOf(pkg) : '') + '"></span>' + esc(pkg) + '</button>';
  }).join('');
  document.getElementById('tableToggle').textContent = state.table ? 'Chart' : 'Table';
}

function render() {
  writeURL();
  renderControls();
  renderParity();
  renderCounts();
  renderGaps();
}

// ---------------------------------------------------------------------------
// Selection: a package owns its color slot. Turning on a package whose slot is
// already taken turns the holder off rather than painting two lines the same
// color — with eight slots and more packages than that, one of the two rules
// (stable colors, distinct colors) has to give, and this keeps both on screen.
// ---------------------------------------------------------------------------
// dedupeSlots drops later packages that would repeat an earlier one's color,
// and returns what it dropped. It runs on every selection — clicked, restored
// from the URL, or defaulted — because two identically colored lines is the one
// outcome the page must never render.
function dedupeSlots(list) {
  var taken = {}, kept = [], dropped = [];
  list.forEach(function (pkg) {
    var slot = slotOf(pkg);
    if (taken[slot] || kept.length >= SLOTS) { dropped.push(pkg); return; }
    taken[slot] = pkg;
    kept.push(pkg);
  });
  return { kept: kept, dropped: dropped };
}

function toggle(pkg) {
  var note = document.getElementById('note');
  note.textContent = '';
  var at = state.selected.indexOf(pkg);
  if (at >= 0) { state.selected.splice(at, 1); return true; }
  if (state.selected.length >= data.max_packages) {
    note.textContent = 'At most ' + data.max_packages + ' packages at once — deselect one first.';
    return false;
  }
  // The clicked package wins its slot; whoever held it steps aside.
  var slot = slotOf(pkg);
  var clash = state.selected.filter(function (p) { return slotOf(p) === slot; });
  clash.forEach(function (p) { state.selected.splice(state.selected.indexOf(p), 1); });
  state.selected.push(pkg);
  if (clash.length) note.textContent = 'Swapped out ' + clash.join(', ') + ' — it shares a color slot with ' + pkg + '.';
  return true;
}

document.getElementById('metricChips').addEventListener('click', function (e) {
  var b = e.target.closest('[data-metric]'); if (!b) return;
  var key = b.dataset.metric, at = state.metrics.indexOf(key);
  if (at >= 0) {
    // The last run may not be turned off: an empty chart teaches nothing, and
    // the picker gives no hint how to get back.
    if (state.metrics.length === 1) {
      document.getElementById('note').textContent = 'Keep at least one run — pick another before dropping this one.';
      return;
    }
    state.metrics.splice(at, 1);
  } else {
    state.metrics.push(key);
  }
  state.gap = null;
  load();
});
document.getElementById('daysSeg').addEventListener('click', function (e) {
  var b = e.target.closest('[data-days]'); if (!b) return;
  state.days = b.dataset.days; load();
});
document.getElementById('chips').addEventListener('click', function (e) {
  var b = e.target.closest('[data-pkg]'); if (!b) return;
  if (toggle(b.dataset.pkg)) load(); else renderControls();
});
document.getElementById('gapSeg').addEventListener('click', function (e) {
  var b = e.target.closest('[data-gap]'); if (!b) return;
  state.gap = b.dataset.gap; renderGaps();
});
document.getElementById('tableToggle').addEventListener('click', function () {
  state.table = !state.table; renderControls(); renderParity();
});

var resizeTimer = null;
window.addEventListener('resize', function () {
  clearTimeout(resizeTimer);
  resizeTimer = setTimeout(function () { if (data) render(); }, 150);
});

// ---------------------------------------------------------------------------
// Load
// ---------------------------------------------------------------------------
function load() {
  var bodies = document.querySelectorAll('.card-body');
  // Refetch keeps the frame: hold the previous render at reduced opacity.
  if (data) bodies.forEach(function (b) { b.classList.add('loading'); });
  var url = '/graphs/parity/data?metrics=' + encodeURIComponent(state.metrics.join(',')) +
    '&days=' + encodeURIComponent(state.days) +
    '&packages=' + encodeURIComponent(state.selected.join(','));
  fetch(url).then(function (r) { return r.json(); }).then(function (d) {
    var err = document.getElementById('err');
    if (d.error) {
      err.style.display = ''; err.textContent = 'parity query failed: ' + d.error;
      bodies.forEach(function (b) { b.classList.remove('loading'); });
      return;
    }
    err.style.display = 'none';
    data = d;
    packages = d.packages || [];
    metrics = d.metrics || [];
    // The picker only offers runs this DB can chart, so a bookmarked URL naming
    // a run whose column the sync has not written yet falls back rather than
    // leaving the page with nothing selected.
    state.metrics = state.metrics.filter(function (k) {
      return metrics.some(function (m) { return m.key === k; });
    });
    if (!state.metrics.length && metrics.length) state.metrics = [metrics[0].key];
    // Drop any preset selection this DB doesn't have (packages come and go as
    // the port grows), and fall back to the first few so the page is never bare.
    state.selected = state.selected.filter(function (p) { return packages.indexOf(p) >= 0; });
    if (!state.selected.length && packages.length && !state.touched) {
      state.selected = packages.slice(0, 3);
      state.touched = true;
      load();
      return;
    }
    state.touched = true;

    // Enforce one-package-per-color-slot on whatever we ended up with. The
    // server already sent every requested series, so a dropped package is just
    // filtered out here rather than costing a second round trip.
    var note = document.getElementById('note');
    var fit = dedupeSlots(state.selected);
    state.selected = fit.kept;
    data.series = (data.series || []).filter(function (s) { return fit.kept.indexOf(s.package) >= 0; });
    // A bookmarked URL can also name packages none of the selected runs have
    // (the calls runs chart one synthetic "all"); the server ignores those and
    // lists them here rather than failing the whole request.
    var absent = d.unknown_packages || [];
    var lines = (data.series || []).length;
    note.textContent = fit.dropped.length
      ? 'Dropped ' + fit.dropped.join(', ') + ' — only ' + SLOTS + ' distinct series colors, and each was already spoken for.'
      : (absent.length
        ? 'Ignored ' + absent.join(', ') + ' — not measured by any selected run.'
        : (lines > 12
          ? lines + ' lines on one chart: color is the package, line style the run. Drop a run or a package if it reads as noise.'
          : ''));

    bodies.forEach(function (b) { b.classList.remove('loading'); });
    render();
  }).catch(function (e) {
    var el = document.getElementById('err'); el.style.display = ''; el.textContent = 'Failed to load parity data: ' + e;
    bodies.forEach(function (b) { b.classList.remove('loading'); });
  });
}
load();
